def merge_intervals(intervals):
    if not intervals:
        return []
    ordered = sorted([list(iv) for iv in intervals], key=lambda x: x[0])
    out = [ordered[0]]
    for s, e in ordered[1:]:
        if s <= out[-1][1]:
            out[-1][1] = max(out[-1][1], e)
        else:
            out.append([s, e])
    return out
