def expr_eval(s):
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        c = s[i]
        if c == ' ':
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            tokens.append(int(s[i:j]))
            i = j
        else:
            tokens.append(c)
            i += 1
    pos = 0
    def peek():
        return tokens[pos] if pos < len(tokens) else None
    def parse_expr():
        nonlocal pos
        val = parse_term()
        while peek() in ('+', '-'):
            op = tokens[pos]; pos += 1
            rhs = parse_term()
            val = val + rhs if op == '+' else val - rhs
        return val
    def parse_term():
        nonlocal pos
        val = parse_factor()
        while peek() in ('*', '/'):
            op = tokens[pos]; pos += 1
            rhs = parse_factor()
            if op == '*':
                val = val * rhs
            else:
                q = abs(val) // abs(rhs)
                val = q if (val >= 0) == (rhs >= 0) else -q
        return val
    def parse_factor():
        nonlocal pos
        tok = tokens[pos]
        if tok == '(':
            pos += 1
            val = parse_expr()
            pos += 1
            return val
        if tok == '-':
            pos += 1
            return -parse_factor()
        pos += 1
        return tok
    return parse_expr()
```

