def json_pointer(obj, pointer):
    if pointer == '':
        return obj
    if not pointer.startswith('/'):
        raise ValueError('pointer must start with /')
    cur = obj
    for raw in pointer[1:].split('/'):
        token = raw.replace('~1', '/').replace('~0', '~')
        if isinstance(cur, list):
            cur = cur[int(token)]
        else:
            cur = cur[token]
    return cur
